python3 - <<'PY'
import tarfile
want = set(open('hold/SHAS.txt').read().split())
have = set()
with tarfile.open('/project/community/jjyeung/okh7/e6fc152498/a2.tar', 'r:') as tf:
    for m in tf:
        if m.isfile() and m.name.startswith('f/'): have.add(m.name.split('/')[-1].split('.')[0])
print('frames wanted', len(want), 'present in a2.tar', len(want & have))
PY
